#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-y-1] [n-y..n-1] -> [n-y..n-1] [x..n-y-1] [0..x-1]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n-2; placed++){
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // Step 1: Move element from pos to the last position (index n-1)
        if(pos != n-1){
            // We want to move p[pos] to position n-1.
            // Use x = pos+1, y = n-1-pos. Then suffix = p[pos+1..n-1], prefix = p[0..pos].
            // Result: [p[pos+1..n-1]] [middle is empty if x+y=n, but x+y = pos+1+n-1-pos = n, need x+y<n]
            // So we can't have empty middle. Use x=pos, y=n-1-pos if pos>0
            // Result: [p[pos+1..n-1]] [p[pos]] [p[0..pos-1]] -> element at position n-1-pos-1+1 = y = n-1-pos... 
            // Actually: suffix=[n-(n-1-pos)..n-1]=[pos+1..n-1], middle=[pos..pos], prefix=[0..pos-1]
            // Result: [pos+1..n-1] [pos] [0..pos-1] -> element at position y = n-1-pos
            if(pos > 0 && (n-1-pos) > 0 && pos + (n-1-pos) < n) {
                ops.push_back({pos, n-1-pos});
                apply(p, pos, n-1-pos);
                pos = n-1-pos; // element moves to position y (size of suffix = n-1-pos)... wait
                // After op, element was at p[pos] which is in middle (single element). Middle starts at index y = n-1-pos.
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            }
            if(pos != n-1 && pos > 0) {
                // put it at end: x=pos+1, y=n-pos-2 leaves 1 middle, but let's just search again
                // Use x=1, y=n-pos-1 if valid
                int x=pos+1, y=n-pos-2;
                if(x>0&&y>0&&x+y<n){ ops.push_back({x,y}); apply(p,x,y); }
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            }
        }
        if(pos==placed) continue;
        // Step 2: element at pos, move to position 'placed'
        if(pos > placed && placed+1 < n && (n-pos) > 0 && placed+1+(n-pos) < n){
            ops.push_back({placed+1, n-pos});
            apply(p, placed+1, n-pos);
        } else if(pos!=placed){
            int x=placed, y=n-pos;
            if(x>0&&y>0&&x+y<n){ ops.push_back({x,y}); apply(p,x,y); }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
